actions.script:
const out = ec.service.sync().name('ironstone.ComposeServices.upload#ComposeAttachment').parameters({emailMessageId: emailMessageId || null,
    contentFile: contentFile || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {attachmentList: out.attachmentList, uploadList: out.uploadList})

const out = ec.service.sync().name('ironstone.ComposeServices.remove#ComposeAttachment').parameters({emailMessageId: emailMessageId || '',
    emailMessageAttachmentId: emailMessageAttachmentId || ''}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {attachmentList: out.attachmentList})

const out = ec.service.sync().name('ironstone.ComposeServices.cancel#ComposeSend').parameters({emailMessageId: emailMessageId || null,
    communicationEventIdsJson: communicationEventIdsJson || null}).call()
ec.web.sendJsonResponse(ec.message.hasError() ? {} : {statusId: out.statusId})

// the qvt render (quick create's dialog) is the component in a container, with the query it was asked with
const names = ['emailMessageId', 'to', 'cc', 'bcc', 'subject', 'body', 'recordEntity', 'recordId', 'recordTitle', 'replyToCommEventId',
    'replyToEmailMessageId', 'forwardEmailMessageId', 'replyAll', 'replyToSender', 'contactListId']
const query = ['mode=embedded']
for (const name of names) {
    const value = context.get(name)
    if (value != null && value !== '') query.push(encodeURIComponent(name) + '=' + encodeURIComponent(String(value)))
}
// as an attribute value: the query is URL encoded already, so only & needs its entity
composeComponentUrl = ('/apps/Comms/Inbox/Compose.qvue?' + query.join('&')).replace(/&/g, '&amp;').replace(/"/g, '&quot;')
